def distinctPrimeFactors(self, nums):
    primes = set()
    for x in nums:
        d = 2
        while d * d <= x:
            while x % d == 0:
                primes.add(d)
                x //= d
            d += 1
        if x > 1:
            primes.add(x)
    return len(primes)

