def goodBinaryStrings(self, minLength, maxLength, oneGroup, zeroGroup):
    MOD = 10**9 + 7
    dp = [0] * (maxLength + 1)
    dp[0] = 1
    res = 0
    for i in range(maxLength + 1):
        if dp[i] == 0:
            continue
        if i + zeroGroup <= maxLength:
            dp[i + zeroGroup] = (dp[i + zeroGroup] + dp[i]) % MOD
