def minCost(self, nums, k):
    n = len(nums)
    dp = [float('inf')] * (n + 1)
    dp[0] = 0
    for i in range(1, n + 1):
        cnt = {}
        importance = 0
        for j in range(i, 0, -1):
            x = nums[j-1]
            cnt[x] = cnt.get(x, 0) + 1
            if cnt[x] == 2:
                importance += 2
            elif cnt[x] > 2:
