            dp[i] = min(dp[i], dp[j-1] + importance + k)
    return dp[n]

def maxPrice(self, items, capacity):
    items.sort(key=lambda x: x[0]/x[1], reverse=True)
    res = 0
    for price, weight in items:
        if capacity >= weight:
            res += price
            capacity -= weight
        else:
            res += price * capacity / weight
            capacity = 0
            break
    return res if capacity == 0 else -1

