def isPossibleToCutPath(self, grid):
    m, n = len(grid), len(grid[0])
    def dfs(i, j):
        if i == m-1 and j == n-1:
            return True
        grid[i][j] = 0
        if i+1 < m and grid[i+1][j] and dfs(i+1, j):
            return True
        if j+1 < n and grid[i][j+1] and dfs(i, j+1):
