def handleQuery(self, nums1, nums2, queries):
    n = len(nums1)
    # Segment tree for nums1 bit flips
    tree = [0] * (4 * n)
    lazy = [False] * (4 * n)
    def build(node, l, r):
        if l == r:
            tree[node] = nums1[l]
            return
        mid = (l + r) // 2
        build(2*node, l, mid)
        build(2*node+1, mid+1, r)
        tree[node] = tree[2*node] + tree[2*node+1]
    def push_down(node, l, r):
        if lazy[node]:
            mid = (l + r) // 2
            tree[2*node] = (mid - l + 1) - tree[2*node]
            tree[2*node+1] = (r - mid) - tree[2*node+1]
            lazy[2*node] ^= True
            lazy[2*node+1] ^= True
            lazy[node] = False
    def update(node, l, r, ql, qr):
        if ql <= l and r <= qr:
            tree[node] = (r - l + 1) - tree[node]
            lazy[node] ^= True
            return
        push_down(node, l, r)
        mid = (l + r) // 2
        if ql <= mid: update(2*node, l, mid, ql, qr)
        if qr > mid: update(2*node+1, mid+1, r, ql, qr)
        tree[node] = tree[2*node] + tree[2*node+1]
    build(1, 0, n-1)
    sum2 = sum(nums2)
    res = []
    for t, a, b in queries:
        if t == 1:
            update(1, 0, n-1, a, b)
        elif t == 2:
            sum2 += tree[1] * b
        else:
            res.append(sum2)
    return res

def mergeArrays(self, nums1, nums2):
